CREATE TABLE "public"."purchase_order_items" (
  "id"                   bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "purchase_tracking_id" bigint                   NOT NULL,
  "item_type"            text                     NOT NULL,
  "quantity"             integer                  DEFAULT 1,
  "part_description"     text                     NOT NULL,
  "company"              text,
  "is_received"          boolean                  DEFAULT false,
  "created_at"           timestamp with time zone DEFAULT now(),
  "po_number"            text,
  "qty_received"         integer                  DEFAULT 0,
  "updated_at"           timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "purchase_order_items_pkey" PRIMARY KEY (id),
  CONSTRAINT "purchase_order_items_purchase_tracking_id_fkey" FOREIGN KEY (purchase_tracking_id) REFERENCES public.purchase_tracking(purchase_check_id) ON DELETE CASCADE
);

ALTER TABLE "public"."purchase_order_items"
  ENABLE ROW LEVEL SECURITY;

CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON public.purchase_order_items
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_updated_at();

CREATE POLICY "Enable delete for admin only" ON "public"."purchase_order_items"
  FOR DELETE
  TO PUBLIC
  USING ((public.clerk_user_role() = 'admin'::text));

CREATE POLICY "Enable insert for purchasing editors" ON "public"."purchase_order_items"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'scheduler'::text])));

CREATE POLICY "Enable read access for authenticated users" ON "public"."purchase_order_items"
  FOR SELECT
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable update for purchasing editors" ON "public"."purchase_order_items"
  FOR UPDATE
  TO PUBLIC
  USING ((public.clerk_user_role() = ANY (ARRAY['admin'::text, 'scheduler'::text])));

REVOKE ALL ON SEQUENCE "public"."purchase_order_items_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."purchase_order_items_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."purchase_order_items_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."purchase_order_items_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."purchase_order_items_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."purchase_order_items_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."purchase_order_items_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."purchase_order_items_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."purchase_order_items" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."purchase_order_items" TO "service_role";

REVOKE ALL ON TABLE "public"."purchase_order_items" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."purchase_order_items" TO "postgres";
